    period = params.get("bollinger_period", 20)
    if len(df) < period + 10:
        return None

    close = df["close"]
    sma = close.rolling(window=period).mean()
    std = close.rolling(window=period).std()
    upper_band = sma + (params.get("bollinger_std", 2.0) * std)
    lower_band = sma - (params.get("bollinger_std", 2.0) * std)

    rsi_vals = rsi(close, params.get("rsi_period", 14))
    atr_vals = atr(df, params.get("atr_period", 14))

    curr_close = float(close.iloc[-1])
    curr_upper = float(upper_band.iloc[-1])
    curr_lower = float(lower_band.iloc[-1])
    curr_rsi = float(rsi_vals.iloc[-1])
    curr_atr = float(atr_vals.iloc[-1])

    prev_close = float(close.iloc[-2])
    prev_upper = float(upper_band.iloc[-2])
    prev_lower = float(lower_band.iloc[-2])

    # Bullish Volatility Expansion
    if prev_close <= prev_upper and curr_close > curr_upper and curr_rsi > 55.0:
        entry = curr_close
        sl = round(curr_close - (1.5 * curr_atr), 2)
        risk = entry - sl
        if risk > 0:
            tp1 = round(entry + (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry + (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "BUY",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Crypto upper volatility squeeze expansion breakout with RSI momentum.",
            }

    # Bearish Volatility Expansion
    elif prev_close >= prev_lower and curr_close < curr_lower and curr_rsi < 45.0:
        entry = curr_close
        sl = round(curr_close + (1.5 * curr_atr), 2)
        risk = sl - entry
        if risk > 0:
            tp1 = round(entry - (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry - (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "SELL",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Crypto lower volatility squeeze expansion breakdown with RSI momentum.",
            }

    return None
', NULL, False, '2026-11-16 22:37:41');
REPLACE INTO `strategy_scripts` (`id`, `name`, `description`, `target_mode`, `python_code`, `default_params_json`, `is_builtin`, `created_at_utc`) VALUES (21, 'Tushar-BTC/GOLD', NULL, 'SCALP', 'DEFAULT_PARAMS = {
    "ema_fast": 21,
    "ema_slow": 50,
    "sweep_lookback": 20,
    "atr_period": 14,
    "atr_sl_mult": 1.4,
    "rr_tp1": 1.5,
    "rr_tp2": 3.2,
    "rsi_period": 14,
}


def evaluate(df, params):
    min_bars = max(params.get("ema_slow", 50), params.get("sweep_lookback", 20)) + 5
    if len(df) < min_bars:
        return None

    close = df["close"]
    high = df["high"]
    low = df["low"]

    fast = ema(close, params.get("ema_fast", 21))
    slow = ema(close, params.get("ema_slow", 50))
    cur_atr = atr(df, params.get("atr_period", 14)).iloc[-1]
    cur_rsi = rsi(close, params.get("rsi_period", 14)).iloc[-1]

    if pd.isna(cur_atr) or cur_atr <= 0:
        return None

    lb = params.get("sweep_lookback", 20)
    prior_low = low.iloc[-(lb + 2):-2].min()
    prior_high = high.iloc[-(lb + 2):-2].max()

    c_close = float(close.iloc[-1])
    prev_low = float(low.iloc[-2])
    prev_high = float(high.iloc[-2])

    # Bullish FVG + Prior Liquidity Low Sweep in Uptrend
    bull_fvg = float(low.iloc[-1]) > float(high.iloc[-3])
    swept_low = (prev_low < prior_low) and (c_close > prior_low)
    if fast.iloc[-1] > slow.iloc[-1] and swept_low and bull_fvg and cur_rsi < 68:
        sl_dist = max(c_close - prev_low, 0.5 * float(cur_atr)) + (params.get("atr_sl_mult", 1.4) * float(cur_atr) * 0.35)
        sl = c_close - sl_dist
        tp1 = c_close + sl_dist * params.get("rr_tp1", 1.5)
        tp2 = c_close + sl_dist * params.get("rr_tp2", 3.2)
        return {
            "signal": "BUY",
            "mode": "SCALP",
            "entry": c_close,
            "sl": sl,
            "tp1": tp1,
            "tp2": tp2,
            "reason": "EMA uptrend + liquidity low sweep + bullish FVG displacement",
        }

    # Bearish FVG + Prior Liquidity High Sweep in Downtrend
    bear_fvg = float(high.iloc[-1]) < float(low.iloc[-3])
    swept_high = (prev_high > prior_high) and (c_close < prior_high)
    if fast.iloc[-1] < slow.iloc[-1] and swept_high and bear_fvg and cur_rsi > 32:
        sl_dist = max(prev_high - c_close, 0.5 * float(cur_atr)) + (params.get("atr_sl_mult", 1.4) * float(cur_atr) * 0.35)
        sl = c_close + sl_dist
        tp1 = c_close - sl_dist * params.get("rr_tp1", 1.5)
        tp2 = c_close - sl_dist * params.get("rr_tp2", 3.2)
        return {
            "signal": "SELL",
            "mode": "SCALP",
            "entry": c_close,
            "sl": sl,
            "tp1": tp1,
            "tp2": tp2,
            "reason": "EMA downtrend + liquidity high sweep + bearish FVG displacement",
        }

    return None', NULL, False, '2026-11-16 22:52:53');
REPLACE INTO `strategy_scripts` (`id`, `name`, `description`, `target_mode`, `python_code`, `default_params_json`, `is_builtin`, `created_at_utc`) VALUES (22, '1. H1/H4 EMA Trend Pullback + ATR', NULL, 'SCALP', 'DEFAULT_PARAMS = {
    "fast_ema": 21,
    "slow_ema": 50,
    "atr_period": 14,
    "atr_sl_mult": 1.5,
    "rr_tp1": 1.5,
    "rr_tp2": 3.0,
}

def evaluate(df, params):
    """
    H1/H4 EMA Trend Pullback + ATR Strategy (SWING).
    Trades institutional trend continuation when price pulls back into the dynamic
    value zone of EMA21 / EMA50 and prints an ATR-confirmed price rejection.
    """
    if len(df) < params.get("slow_ema", 50) + 10:
        return None

    close_series = df["close"]
    fast = ema(close_series, params.get("fast_ema", 21))
    slow = ema(close_series, params.get("slow_ema", 50))
    atr_vals = atr(df, params.get("atr_period", 14))

    curr_close = float(close_series.iloc[-1])
    curr_low = float(df["low"].iloc[-1])
    curr_high = float(df["high"].iloc[-1])
    curr_fast = float(fast.iloc[-1])
    curr_slow = float(slow.iloc[-1])
    curr_atr = float(atr_vals.iloc[-1])

    sl_dist = curr_atr * params.get("atr_sl_mult", 1.5)

    # Uptrend Condition: Fast EMA > Slow EMA and price pulled back to Fast EMA
    if curr_fast > curr_slow and curr_low <= curr_fast and curr_close > curr_fast:
        entry = curr_close
        sl = round(curr_low - sl_dist, 2)
        risk = entry - sl
        if risk > 0:
            tp1 = round(entry + (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry + (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "BUY",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Uptrend EMA value zone pullback rejection confirmed.",
            }

    # Downtrend Condition: Fast EMA < Slow EMA and price pulled back to Fast EMA
    elif curr_fast < curr_slow and curr_high >= curr_fast and curr_close < curr_fast:
        entry = curr_close
        sl = round(curr_high + sl_dist, 2)
        risk = sl - entry
        if risk > 0:
            tp1 = round(entry - (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry - (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "SELL",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Downtrend EMA value zone pullback rejection confirmed.",
            }

    return None
', NULL, False, '2026-11-16 22:58:24');
