-- --------------------------------------------------------
-- Table schema for `backtest_runs`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS backtest_runs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	strategy_id INTEGER, 
	symbol VARCHAR(32) NOT NULL, 
	timeframe VARCHAR(16) NOT NULL, 
	test_mode VARCHAR(32) NOT NULL, 
	capital_usd NUMERIC(14, 2) NOT NULL, 
	total_trades INTEGER NOT NULL, 
	win_rate_pct NUMERIC(5, 2) NOT NULL, 
	gross_pnl_usd NUMERIC(14, 2) NOT NULL, 
	spread_cost_usd NUMERIC(14, 2) NOT NULL, 
	swap_cost_usd NUMERIC(14, 2) NOT NULL, 
	commission_cost_usd NUMERIC(14, 2) NOT NULL, 
	net_pnl_usd NUMERIC(14, 2) NOT NULL, 
	net_roi_pct NUMERIC(8, 2) NOT NULL, 
	max_dd_pct NUMERIC(5, 2) NOT NULL, 
	profit_factor NUMERIC(8, 2) NOT NULL, 
	is_saved_bookmark BOOL NOT NULL, 
	custom_label VARCHAR(128), 
	strategy_code_snapshot TEXT, 
	params_json TEXT, 
	trades_json TEXT, 
	created_at_utc DATETIME NOT NULL, 
	PRIMARY KEY (id)
);

