REPLACE INTO `backtest_runs` (`id`, `strategy_id`, `symbol`, `timeframe`, `test_mode`, `capital_usd`, `total_trades`, `win_rate_pct`, `gross_pnl_usd`, `spread_cost_usd`, `swap_cost_usd`, `commission_cost_usd`, `net_pnl_usd`, `net_roi_pct`, `max_dd_pct`, `profit_factor`, `is_saved_bookmark`, `custom_label`, `strategy_code_snapshot`, `params_json`, `trades_json`, `created_at_utc`) VALUES (22, 1, 'GOLD#', 'H1', 'ACCOUNT_100', 100.00, 2, 0.00, -60.94, 0.98, 0.00, 0.00, -62.00, -62.00, 62.00, 0.00, False, NULL, 'DEFAULT_PARAMS = {
