REPLACE INTO `backtest_runs` (`id`, `strategy_id`, `symbol`, `timeframe`, `test_mode`, `capital_usd`, `total_trades`, `win_rate_pct`, `gross_pnl_usd`, `spread_cost_usd`, `swap_cost_usd`, `commission_cost_usd`, `net_pnl_usd`, `net_roi_pct`, `max_dd_pct`, `profit_factor`, `is_saved_bookmark`, `custom_label`, `strategy_code_snapshot`, `params_json`, `trades_json`, `created_at_utc`) VALUES (49, 2, 'BTCUSD#', 'M5', 'ACCOUNT_100', 100.00, 27, 29.63, 38.05, 10.80, -65.41, 0.00, -38.20, -38.20, 47.56, 1.91, False, NULL, 'DEFAULT_PARAMS = {
    "session_range_bars": 12,
    "atr_period": 14,
    "rr_tp1": 1.5,
    "rr_tp2": 2.5,
}

def evaluate(df, params):
    """
    London & NY Session Breakout Strategy (SCALP).
    Identifies momentum expansion when price breaks out of the pre-session
    range during peak institutional volume windows.
    """
    lookback = params.get("session_range_bars", 12)
    if len(df) < lookback + 5:
        return None

    range_slice = df.iloc[-lookback-1 : -1]
    range_high = float(range_slice["high"].max())
    range_low = float(range_slice["low"].min())
    range_mid = (range_high + range_low) / 2.0

    current_close = float(df["close"].iloc[-1])
    current_open = float(df["open"].iloc[-1])
    prev_close = float(df["close"].iloc[-2])

    atr_vals = atr(df, period=params.get("atr_period", 14))
    current_atr = float(atr_vals.iloc[-1])

    # Bullish Breakout above range high
    if prev_close <= range_high and current_close > range_high:
        entry = current_close
        sl = round(range_mid, 2)
        risk = entry - sl
        if risk > current_atr * 0.5:
            tp1 = round(entry + (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry + (risk * params.get("rr_tp2", 2.5)), 2)
            return {
                "signal": "BUY",
                "mode": "SCALP",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Institutional session range high breakout expansion.",
            }

    # Bearish Breakout below range low
    elif prev_close >= range_low and current_close < range_low:
        entry = current_close
        sl = round(range_mid, 2)
        risk = sl - entry
        if risk > current_atr * 0.5:
            tp1 = round(entry - (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry - (risk * params.get("rr_tp2", 2.5)), 2)
            return {
                "signal": "SELL",
                "mode": "SCALP",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Institutional session range low breakout expansion.",
            }

    return None
