swap_cost": 0.0, "commission": 0.0, "net_pnl": -0.0, "r_multiple": 0.16, "exit_reason": "SL_HIT", "entry_time": "2026-11-15 16:30:00+00:00", "exit_time": "2026-11-15 16:45:00+00:00"}, {"trade_id": 40, "symbol": "BTCUSD#", "direction": "SELL", "mode": "SWING", "lots": 0.01, "entry_price": 64518.25, "exit_price": 64770.07, "gross_pnl": -2.52, "spread_cost": 0.4, "swap_cost": 0.0, "commission": 0.0, "net_pnl": -2.92, "r_multiple": -1.0, "exit_reason": "SL_HIT", "entry_time": "2026-11-15 18:20:00+00:00", "exit_time": "2026-11-15 18:25:00+00:00"}, {"trade_id": 41, "symbol": "BTCUSD#", "direction": "BUY", "mode": "SWING", "lots": 0.01, "entry_price": 64932.25, "exit_price": 64706.05, "gross_pnl": -2.26, "spread_cost": 0.4, "swap_cost": -28.03, "commission": 0.0, "net_pnl": -30.69, "r_multiple": -1.0, "exit_reason": "SL_HIT", "entry_time": "2026-11-15 21:10:00+00:00", "exit_time": "2026-11-15 22:10:00+00:00"}]', '2026-11-16 22:26:47');
REPLACE INTO `backtest_runs` (`id`, `strategy_id`, `symbol`, `timeframe`, `test_mode`, `capital_usd`, `total_trades`, `win_rate_pct`, `gross_pnl_usd`, `spread_cost_usd`, `swap_cost_usd`, `commission_cost_usd`, `net_pnl_usd`, `net_roi_pct`, `max_dd_pct`, `profit_factor`, `is_saved_bookmark`, `custom_label`, `strategy_code_snapshot`, `params_json`, `trades_json`, `created_at_utc`) VALUES (52, 4, 'BTCUSD#', 'M15', 'ACCOUNT_100', 100.00, 38, 13.16, -40.39, 15.20, -65.41, 0.00, -121.12, -121.12, 121.12, 0.49, False, NULL, 'DEFAULT_PARAMS = {
    "bollinger_period": 20,
    "bollinger_std": 2.0,
    "rsi_period": 14,
    "atr_period": 14,
    "rr_tp1": 1.5,
    "rr_tp2": 3.0,
}

def evaluate(df, params):
    """
    24/7 Crypto Volatility Squeeze Strategy (BOTH Scalp & Swing).
    Specifically tuned for 24/7 crypto CFDs (BTCUSD#, ETHUSD#, SOLUSD#).
    Detects volatility compression squeezes followed by explosive expansion impulses.
    """
    period = params.get("bollinger_period", 20)
    if len(df) < period + 10:
        return None

    close = df["close"]
    sma = close.rolling(window=period).mean()
    std = close.rolling(window=period).std()
    upper_band = sma + (params.get("bollinger_std", 2.0) * std)
    lower_band = sma - (params.get("bollinger_std", 2.0) * std)

    rsi_vals = rsi(close, params.get("rsi_period", 14))
    atr_vals = atr(df, params.get("atr_period", 14))

    curr_close = float(close.iloc[-1])
    curr_upper = float(upper_band.iloc[-1])
    curr_lower = float(lower_band.iloc[-1])
    curr_rsi = float(rsi_vals.iloc[-1])
    curr_atr = float(atr_vals.iloc[-1])

    prev_close = float(close.iloc[-2])
    prev_upper = float(upper_band.iloc[-2])
    prev_lower = float(lower_band.iloc[-2])

    # Bullish Volatility Expansion
    if prev_close <= prev_upper and curr_close > curr_upper and curr_rsi > 55.0:
        entry = curr_close
        sl = round(curr_close - (1.5 * curr_atr), 2)
        risk = entry - sl
        if risk > 0:
            tp1 = round(entry + (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry + (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "BUY",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Crypto upper volatility squeeze expansion breakout with RSI momentum.",
            }

    # Bearish Volatility Expansion
    elif prev_close >= prev_lower and curr_close < curr_lower and curr_rsi < 45.0:
        entry = curr_close
        sl = round(curr_close + (1.5 * curr_atr), 2)
        risk = sl - entry
        if risk > 0:
            tp1 = round(entry - (risk * params.get("rr_tp1", 1.5)), 2)
            tp2 = round(entry - (risk * params.get("rr_tp2", 3.0)), 2)
            return {
                "signal": "SELL",
                "mode": "SWING",
                "entry": entry,
                "sl": sl,
                "tp1": tp1,
                "tp2": tp2,
                "reason": "Crypto lower volatility squeeze expansion breakdown with RSI momentum.",
            }

    return None
