-- Table schema for `trade_ledger`
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS trade_ledger (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	account_type VARCHAR(8) NOT NULL, 
	position_id BIGINT NOT NULL, 
	order_ticket BIGINT, 
	symbol VARCHAR(32) NOT NULL, 
	magic_number INTEGER NOT NULL, 
	mode VARCHAR(16) NOT NULL, 
	direction VARCHAR(8) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	lots NUMERIC(10, 4) NOT NULL, 
	initial_lots NUMERIC(10, 4) NOT NULL, 
	entry_price NUMERIC(18, 6) NOT NULL, 
	sl NUMERIC(18, 6) NOT NULL, 
	tp1 NUMERIC(18, 6) NOT NULL, 
	tp2 NUMERIC(18, 6) NOT NULL, 
	exit_price NUMERIC(18, 6), 
	entry_spread_points INTEGER NOT NULL, 
	slippage_points INTEGER NOT NULL, 
	gross_pnl NUMERIC(14, 2) NOT NULL, 
	commission NUMERIC(14, 2) NOT NULL, 
	swap NUMERIC(14, 2) NOT NULL, 
	net_pnl NUMERIC(14, 2) NOT NULL, 
	r_multiple NUMERIC(8, 2), 
	mae_r NUMERIC(8, 2), 
	mfe_r NUMERIC(8, 2), 
	exit_reason VARCHAR(32), 
	strategy_id INTEGER, 
	ai_analysis_summary TEXT, 
	loss_postmortem_text TEXT, 
	opened_at_utc DATETIME NOT NULL, 
	closed_at_utc DATETIME, 
	PRIMARY KEY (id)
);

